import{d,C as n,o as g,c as h,a3 as e,E as s,j as a,a as p}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第五章","description":"《正易心法》第五章——六十四卦无穷妙义尽在画中：蒙取次于艮、师取次于坤，卦序之次非私意，乃阴阳运动、血气流行的自然之理。","frontmatter":{"title":"正易心法·第五章","description":"《正易心法》第五章——六十四卦无穷妙义尽在画中：蒙取次于艮、师取次于坤，卦序之次非私意，乃阴阳运动、血气流行的自然之理。","category":"guide","aliases":["正易心法第五章","无穷妙义尽在画中","取次于"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-05.md","filePath":"yijing/zheng-yi-xin-fa/chapter-05.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-05.md"},q=d({...c,setup(u){const i=[{id:"z5-01",label:"一、尽在画中",showLabel:!0,sentences:[["六十四卦，无穷妙义，",{text:"尽在画中",glossary:"jinzaiHua"},"，合为自然。"]],note:["六十四卦的无穷妙义，全部在卦画之中，合于自然之理。（这一句是本章的总纲，也是前四章理论的第一次具体落实——由「象为本」推到了「卦序也是象」。）"]},{id:"z5-02",label:"二、蒙取次于艮",showLabel:!0,sentences:[["无穷妙义，若蒙必",{text:"取次于",glossary:"quciyu"},"艮，师必取次于坤，是大有旨意也。"]],note:["所谓「无穷妙义」：比如蒙卦必然紧接在艮之后（蒙的上卦即艮），师卦必然紧接在坤之后（师的上卦即坤），这其中有深意。麻衣在这里把《序卦传》的文字逻辑，还原为卦画的结构逻辑——蒙之所以有「蒙」义，是因为上艮下坎：山止于外，险伏于内。"]},{id:"z5-03",label:"三、不止于卦辞",showLabel:!0,sentences:[["不止于贞丈人吉，童蒙求我之义。"]],note:["绝不止于「贞，丈人吉」（师卦卦辞）或「童蒙求我」（蒙卦卦辞）这些文字表面的意思。（卦辞只是对那个卦画状态的一句话描述，不是本义。要问的不是「为什么卦辞这么说」，而是「卦画本身是什么样子」。）"]},{id:"z5-04",label:"四、非是私意",showLabel:!0,sentences:[["合为自然，谓次艮、次坤，非是",{text:"私意",glossary:"siyi"},"，"]],note:["所谓「合为自然」，是说蒙次艮、师次坤这样的安排，并非出于人的主观安排。（「私意」与「自然」相对——卦序不是谁设计出来的，是卦画结构自己排出来的。）"]},{id:"z5-05",label:"五、皆自然之理",showLabel:!0,sentences:[["乃阴阳运动，血气流行，其所",{text:"施为",glossary:"shiwei"},"，皆自然之理也。"]],note:["而是阴阳运动、血气流行，它的运作方式都合于自然之理。（这一句几乎是第二章结尾「卦画凡以此顺此理而已」的原话重现。第二章说的是卦画本身是自然节律，本章说的是卦与卦之间的关系也是自然节律——不是重复，是深化。）"]}],o=[{id:"jinzaiHua",term:"尽在画中",pinyin:"jìn zài huà zhōng",meaning:"全部在卦画之中。呼应第三章「本无文字」。"},{id:"quciyu",term:"取次于",pinyin:"qǔ cì yú",meaning:"紧接排列于……之后。指卦序中的前后相邻关系，也含卦画结构上的关联（如蒙之上卦即艮）。"},{id:"siyi",term:"私意",pinyin:"sī yì",meaning:"个人主观意图。与「自然」相对，指人为安排。"},{id:"shiwei",term:"施为",pinyin:"shī wéi",meaning:"所作所为、运作方式。此处指卦序的排列运作。"}];return(b,t)=>{const r=n("DaoTextReading"),l=n("DaoKeywordCards");return g(),h("div",null,[t[0]||(t[0]=e("",16)),s(r,{colophon:"无穷妙义 · 尽在画中 · 取次于艮坤 · 皆自然之理",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第五章原文",sections:i,glossary:o}),t[1]||(t[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),t[2]||(t[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(l,{items:[{term:"取次于",pinyin:["qǔ","cì","yú"],meaning:"紧接排列于……之后。既指卦序中的相邻关系，也含卦画结构上的关联（蒙之上卦即艮）。"},{term:"私意",pinyin:["sī","yì"],meaning:"与「自然」相对，指人为安排。麻衣说卦序非私意，乃卦画结构自己排出来的。"},{term:"蒙 · 艮",pinyin:["méng","gèn"],meaning:"蒙☶☵（上艮下坎）：山止于外、险伏于内，正是蒙昧未开之象。故曰「蒙取次于艮」。"},{term:"师 · 坤",pinyin:["shī","kūn"],meaning:"师☷☵（上坤下坎）：大地包容、地中藏水，正是众聚之象。故曰「师取次于坤」。"}]}),t[3]||(t[3]=e("",23))])}}});export{y as __pageData,q as default};
